_EMBEDDED_DATA_B64 = ""

def _embedded_payload():
    if not hasattr(_embedded_payload, "cache"):
        try:
            _embedded_payload.cache = json.loads(zlib.decompress(base64.b64decode(_EMBEDDED_DATA_B64)).decode("utf-8"))
        except Exception:
            _embedded_payload.cache = {"records": [], "documents": [], "website_sources": []}
    return _embedded_payload.cache

