@st.cache_data(ttl=3600, show_spinner=False)
def fetch_webpage(url):
    """Download one page. Failures are RAISED (not returned) so Streamlit does not cache them."""
    import time
    headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36",
               "Accept": "text/html,application/xhtml+xml", "Accept-Language": "en-US,en;q=0.9"}
    response = None
    for attempt in range(3):
        try:
            response = requests.get(url, headers=headers, timeout=20)
            response.raise_for_status()
            break
        except Exception:
            response = None
            time.sleep(1 + attempt)
    if response is None:
        raise RuntimeError("download failed: " + url)

    from bs4 import BeautifulSoup
    soup = BeautifulSoup(response.text, "html.parser")
    for tag in soup(["script", "style", "noscript", "svg", "iframe", "nav", "footer"]):
        tag.decompose()
    title = clean_text(soup.title.get_text()) if soup.title else ""

    heading_tags = {"h1", "h2", "h3", "h4", "h5", "h6"}
    block_tags = {"div", "p", "li", "ul", "ol", "table", "tr", "td", "th", "section", "article",
                  "header", "aside", "form", "figure", "main", "details", "summary",
                  "blockquote", "dl", "dt", "dd"}
    nested = list(block_tags | heading_tags)
    current, groups, seen_text = (title or "VU Official Website"), {}, set()
    for el in soup.find_all(True):
        if el.name in heading_tags:
            heading = clean_text(el.get_text(" "))
            if heading:
                current = heading
                groups.setdefault(current, [])
            continue
        if el.name not in block_tags:
            continue
        if el.find(nested):  # only the text sitting directly in this block
            parts = []
            for child in el.children:
                if child.__class__.__name__ == "NavigableString":
                    parts.append(str(child))
                elif getattr(child, "name", None) and child.name not in block_tags \
                        and child.name not in heading_tags and not child.find(nested):
                    parts.append(child.get_text(" "))
            txt = clean_text(" ".join(parts))
        else:
            txt = clean_text(el.get_text(" "))
        if len(txt) < 2 or txt in seen_text:
            continue
        seen_text.add(txt)
        groups.setdefault(current, []).append(txt)
    sections = [{"section": h, "text": " | ".join(items)} for h, items in groups.items() if items]
    if not sections:
        sections = [{"section": title or "VU Official Website",
                     "text": clean_text(soup.get_text(separator=" "))}]
    return {"title": title, "sections": sections}

def fetch_webpage_safe(url):
    try:
        return fetch_webpage(url)
    except Exception as exc:
        return {"title": "", "sections": [], "_error": f"{type(exc).__name__}: {exc}"}

SKIP_LINK_PARTS = ("/wp-content/", "/wp-json", "/wp-admin", "/feed", "/tag/", "/author/", "/cdn-cgi/")

SKIP_LINK_EXT = (".pdf", ".jpg", ".jpeg", ".png", ".gif", ".svg", ".webp", ".zip",
                 ".doc", ".docx", ".xls", ".xlsx", ".ppt", ".pptx", ".mp4", ".mp3")

@st.cache_data(ttl=3600, show_spinner=False)
def fetch_sublinks(url):
    """Return same-website links found on a page (menus included)."""
    try:
        from urllib.parse import urljoin, urlparse
        from bs4 import BeautifulSoup
        headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"}
        response = requests.get(url, headers=headers, timeout=20)
        response.raise_for_status()
        soup = BeautifulSoup(response.text, "html.parser")
        base_host = urlparse(url).netloc.replace("www.", "")
        links = []
        for a in soup.find_all("a", href=True):
            href = a["href"].strip()
            if href.startswith(("#", "mailto:", "tel:", "javascript:")):
                continue
            full = urljoin(url, href).split("#")[0].split("?")[0]
            parsed = urlparse(full)
            if parsed.scheme not in ("http", "https"):
                continue
            if parsed.netloc.replace("www.", "") != base_host:
                continue
            if parsed.path.lower().endswith(SKIP_LINK_EXT):
                continue
            if any(part in parsed.path.lower() for part in SKIP_LINK_PARTS):
                continue
            if not full.endswith("/") and "." not in parsed.path.rsplit("/", 1)[-1]:
                full += "/"
            if full not in links:
                links.append(full)
        return links
    except Exception:
        return []

@st.cache_data(ttl=3600, show_spinner=False)
def fetch_sitemap_urls(origin):
    """Read the website's sitemap(s) (if any) and return all page URLs listed there."""
    found = []
    queue = [origin + "/sitemap.xml", origin + "/sitemap_index.xml", origin + "/wp-sitemap.xml"]
    visited = set()
    headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"}
    while queue and len(visited) < 40:
        sitemap = queue.pop(0)
        if sitemap in visited:
            continue
        visited.add(sitemap)
        try:
            response = requests.get(sitemap, headers=headers, timeout=20)
            if response.status_code != 200:
                continue
            locations = re.findall(r"<loc>\s*(.*?)\s*</loc>", response.text, re.S)
        except Exception:
            continue
        for loc in locations:
            loc = html.unescape(loc.strip())
            if loc.lower().endswith(".xml"):
                queue.append(loc)
            elif loc not in found:
                found.append(loc)
    return found

def expand_with_sublinks(sources):
    """Add every sub-page of each listed link (one level deep) plus sitemap pages to the source list."""
    if not CRAWL_SUBLINKS:
        return sources
    from urllib.parse import urlparse
    expanded = list(sources)
    seen = {src.get("url", "").rstrip("/") for src in sources}

    def add(name, link):
        key = link.rstrip("/")
        if key in seen or len(expanded) >= MAX_TOTAL_PAGES:
            return
        seen.add(key)
        expanded.append({"name": name, "url": link})

    origins = {}
    for source in sources:
        url = source.get("url", "")
        if not url:
            continue
        parsed = urlparse(url)
        origins[f"{parsed.scheme}://{parsed.netloc}"] = parsed.netloc.replace("www.", "")
        for link in fetch_sublinks(url):
            add(source.get("name", "VU Official Website"), link)

    for origin, host in origins.items():
        for link in fetch_sitemap_urls(origin):
            parsed = urlparse(link)
            if parsed.scheme not in ("http", "https") or parsed.netloc.replace("www.", "") != host:
                continue
            if parsed.path.lower().endswith(SKIP_LINK_EXT):
                continue
            if any(part in parsed.path.lower() for part in SKIP_LINK_PARTS):
                continue
            add("VU Official Website", link)
    return expanded

def load_website_documents():
    from concurrent.futures import ThreadPoolExecutor
    documents = []
    sources = [src for src in expand_with_sublinks(load_website_sources()) if src.get("url")]
    # Fetch many pages at the same time so loading stays fast
    with ThreadPoolExecutor(max_workers=6) as pool:
        pages = list(pool.map(lambda src: fetch_webpage_safe(src["url"]), sources))
    failed_urls = []
    loaded_urls = set()
    for source, page in zip(sources, pages):
        if page.get("_error") or not page.get("sections"):
            failed_urls.append({"url": source.get("url", ""), "error": page.get("_error", "No text extracted")})
        name = source.get("name", "VU Official Website")
        url = source.get("url", "")
        for section_info in page.get("sections", []):
            text = section_info.get("text", "")
            if not text:
                continue
            loaded_urls.add(url)
            for i, chunk in enumerate(chunk_text(text, chunk_size=180, overlap=40), start=1):
                documents.append({
                    "text": chunk,
                    "source": name,
                    "url": url,
                    "title": page.get("title", ""),
                    "section": section_info.get("section", ""),
                    "type": "website",
                    "chunk": i
                })
    st.session_state.website_load_summary = {
        "configured_pages": len(sources), "pages_with_text": len(loaded_urls),
        "website_chunks": len(documents), "failed_pages": failed_urls[:30]
    }
    return documents


